// Catalog JSON contract (public/catalog/<mission>.json). Generated by scripts/build_catalog.py.

export type ArgType = 'str' | 'int' | 'float' | 'bool' | 'datetime' | 'enum' | 'list' | 'any';

export interface CatalogEnum {
  /** name = Python member name e.g. ACCEPTANCE___COMPLETION, value = 'Acceptance | Completion' */
  members: { name: string; value: string | number }[];
}

export interface CatalogArg {
  /** python kwarg / field name, e.g. On_Off_State */
  name: string;
  /** actual_name sent to MCS (usually == name) */
  wire: string;
  type: ArgType;
  /** enum class name when type==='enum', e.g. PusAckFlagsEnum */
  enum?: string;
  required: boolean;
  default?: string | number | boolean | null;
  description?: string;
}

export interface CatalogCommand {
  /** qualified name, e.g. /FF/EPS/Swt_aocs3v3BkMn */
  q: string;
  /** segment after mission, e.g. EPS */
  subsystem: string;
  description?: string;
  /** user-settable args only (not pre-assigned), in declaration order */
  args: CatalogArg[];
  /** pre-assigned args (Base_ID, Command_ID, Pus_Service_Type...) wire-name -> value */
  fixed: Record<string, string>;
}

export interface CatalogParameter {
  /** /FF/AOCS/Aocs_Mode */
  q: string;
  subsystem: string;
  kind: 'normal' | 'enumeration' | 'aggregate';
  /** value field name in the generated class, e.g. Aocs_Mode */
  field: string;
  type: 'float' | 'int' | 'str' | 'bool' | 'enum' | 'any';
  enum?: string;
  description?: string;
}

export interface Catalog {
  mission: 'FF' | 'JTYU';
  /** e.g. 'mos-framework @ <git short sha> (generated 2026-04-21)' */
  source: string;
  /** ISO */
  generatedAt: string;
  /** enums defined in commands.py (accessible as `comm.<EnumName>`) */
  enums: Record<string, CatalogEnum>;
  /** enums defined in parameters.py (accessible as `param.<EnumName>`) */
  paramEnums: Record<string, CatalogEnum>;
  /** key = Python class name, e.g. EPSSwtAocs3v3BkMn */
  commands: Record<string, CatalogCommand>;
  /** key = Python class name, e.g. AOCSAocsMode */
  parameters: Record<string, CatalogParameter>;
}
